// RAVEL observer: bounded, progressive stdout records; no RNG or inference.
size_t _trace_event = 0, _trace_sequence = 0, _trace_bytes = 0, _trace_final = 0;
std::string _tj(const std::string& v) const {
  std::ostringstream s; s << '"';
  for (unsigned char c : v) {
    if (c == '"' || c == '\\') s << '\\' << c;
    else if (c < 32) s << "\\u00" << std::hex << std::setw(2) << std::setfill('0') << int(c) << std::dec;
    else s << c;
  }
  s << '"'; return s.str();
}
std::string _tj(const char* v) const { return _tj(std::string(v)); }
std::string _tj(double v) const {
  if (!std::isfinite(v)) return _tj(std::isnan(v) ? "NaN" : (v > 0 ? "+Infinity" : "-Infinity"));
  std::ostringstream s; s.imbue(std::locale::classic()); s << std::setprecision(17) << v; return s.str();
}
template<class T> std::string _ta(const T& v) const {
  std::string s="["; for (size_t i=0;i<v.size();++i) { if(i) s+=","; s+=_tj(v[i]); } return s+"]";
}
std::string _tp(const P4& p) const {
  return _ta(vector<double>{p.E(),p.px(),p.py(),p.pz(),p.pT(),p.eta(),p.phi(),p.mass()});
}
template<class T> std::string _to(const T& xs) const {
  std::string s="["; for(size_t i=0;i<xs.size();++i) { if(i) s+=",";s+=_tp(xs[i].mom()); }return s+"]";
}
void _trace(const std::string& phase,const std::string& data) {
  std::string line="RAVEL_HHH_TRACE_V1 {\"seq\":"+std::to_string(++_trace_sequence)+",\"event\":"+std::to_string(_trace_event)+",\"phase\":"+_tj(phase)+",\"data\":"+data+"}\n";
  if(line.size()>1048576 || _trace_bytes+line.size()>67108864) throw std::runtime_error("RAVEL trace byte ceiling");
  _trace_bytes+=line.size(); std::cout << line << std::flush;
  if(!std::cout) throw std::runtime_error("RAVEL trace write failure");
}
vector<float> _tv(const std::string& phase, const vector<float>& v) {
  _trace(phase,_ta(v)); return v;
}
void _veto_trace(const char* reason) { _trace("veto",_tj(reason)); }

